  implicit none

  private

  interface
    function get_Vsq() bind(C, name="ckm_mod_Vsq")
      import :: c_ptr, c_double
      type(c_ptr) :: get_Vsq
    end function get_Vsq
    function get_Vsum() bind(C, name="ckm_mod_Vsum")
      import :: c_ptr, c_double
      type(c_ptr) :: get_Vsum
    end function get_Vsum
  end interface

  public:: Vsq, Vsum, ckm_mod_init, ckm_mod_finalize

  real(c_double), pointer, dimension(:,:) :: Vsq => null()
  real(c_double), pointer, dimension(:) :: Vsum => null()

contains
  subroutine ckm_mod_init()
    implicit none

    real(c_double), dimension(:), pointer :: fptr1 => null()
    real(c_double), dimension(:,:), pointer :: fptr2 => null()
    integer :: i,j

    allocate(Vsq(-nf:nf, -nf:nf),Vsum(-nf:nf))

    call c_f_pointer(get_Vsq(), fptr2, [2*nf+1, 2*nf+1])
    Vsq(-nf:,-nf:) => fptr2
