    call c_f_pointer(get_Vsum(), fptr1, [2*nf+1])
    Vsum(-nf:nf) => fptr1(1:2*nf+1)
    fptr1 => null()

  end subroutine ckm_mod_init
  subroutine ckm_mod_finalize()
    implicit none
    nullify(Vsq,Vsum)
  end subroutine ckm_mod_finalize

